"""Finite closed-window business evidence, not an inference from global Redis INFO."""
import hashlib,json,re
from fractions import Fraction
from decimal import Decimal,InvalidOperation

IDENTIFIER=re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
COUNTERS={'requests','hit_requests','miss_requests','cache_errors','request_errors','bytes','hit_bytes','origin_ms'}
EVENT_FIELDS={'id','business_id','window_id','ts_ms','scope','outcome','lookups','attempts','bytes','cache_ms','origin_ms','queue_ms','request_error'}

def integer(value,minimum=0,maximum=10**12):
    if type(value)is not int or not minimum<=value<=maximum:raise ValueError('bounded integer required')
    return value

def identifier(value):
    if not isinstance(value,str)or not IDENTIFIER.fullmatch(value):raise ValueError('invalid identifier')
    return value

def exact(value,fields):
    if type(value)is not dict or set(value)!=set(fields):raise ValueError('invalid fields')

def loads(text):
    def pairs(items):
        result={}
        for key,value in items:
            if key in result:raise ValueError('duplicate JSON key')
            result[key]=value
        return result
    def constant(value):raise ValueError('nonfinite JSON constant')
    try:return json.loads(text,object_pairs_hook=pairs,parse_constant=constant,parse_float=Decimal)
    except InvalidOperation as error:raise ValueError('invalid decimal JSON number')from error

def validate_spec(spec):
    exact(spec,{'prefix','before','after','businesses','max_origin_ms','minimum_cost_hit_rate'})
    for key in ('prefix','before','after'):identifier(spec[key])
    if spec['before']==spec['after']:raise ValueError('distinct windows required')
    integer(spec['max_origin_ms'],1)
    ratio=spec['minimum_cost_hit_rate'];exact(ratio,{'num','den'});integer(ratio['den'],1,10**6);integer(ratio['num'],0,ratio['den'])
    businesses=spec['businesses']
    if type(businesses)is not list or not 1<=len(businesses)<=8:raise ValueError('bounded business list required')
    seen=set()
    for business in businesses:
        exact(business,{'id','weight','unit_origin_ms','max_p95_ms'});key=identifier(business['id'])
        if key in seen:raise ValueError('duplicate business')
        seen.add(key);integer(business['weight'],1,1000);integer(business['unit_origin_ms'],1,10**6);integer(business['max_p95_ms'],1,10**6)
    return spec

def policy_digest(spec):
    validate_spec(spec)
    return hashlib.sha256(json.dumps(spec,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf-8')).hexdigest()

def number(text):
    if type(text)is not str or not re.fullmatch(r'0|[1-9][0-9]{0,12}',text):raise ValueError('canonical nonnegative native counter required')
    return integer(int(text))

def p95(values):
    if not values:return None
    ordered=sorted(values);return ordered[(95*len(ordered)+99)//100-1]

def derive(snapshot):
    exact(snapshot,{'schema','spec','windows'})
    if type(snapshot['schema'])is not int or snapshot['schema']!=1:raise ValueError('schema')
    spec=validate_spec(snapshot['spec']);packs=snapshot['windows']
    if type(packs)is not list or len(packs)!=2:raise ValueError('two closed windows required')
    windows={};duration=None
    for index,pack in enumerate(packs):
        exact(pack,{'meta','businesses'});meta=pack['meta'];exact(meta,{'id','start_ms','end_ms','closed','unlinked_requests','policy_sha256'})
        name=spec['before']if index==0 else spec['after']
        if meta['id']!=name or meta['closed']!='1'or meta['unlinked_requests']!='0':raise ValueError('window must be closed and fully linked')
        if meta['policy_sha256']!=policy_digest(spec):raise ValueError('policy not bound to the native closed window')
        start=number(meta['start_ms']);end=number(meta['end_ms'])
        if end<=start:raise ValueError('invalid window interval')
        if duration is not None and end-start!=duration:raise ValueError('window durations differ')
        duration=end-start;seen=set();businesses={};all_latencies=[]
        if type(pack['businesses'])is not list or len(pack['businesses'])!=len(spec['businesses']):raise ValueError('missing business evidence')
        for definition,evidence in zip(spec['businesses'],pack['businesses']):
            exact(evidence,{'id','stats','events'});business=definition['id']
            if evidence['id']!=business:raise ValueError('business binding')
            stats=evidence['stats'];exact(stats,COUNTERS|{'window_id','business_id'})
            if stats['window_id']!=name or stats['business_id']!=business:raise ValueError('mixed-window statistics')
            native={key:number(stats[key])for key in COUNTERS}
            events=evidence['events']
            if type(events)is not list or not 1<=len(events)<=128:raise ValueError('bounded complete traces required')
            totals={key:0 for key in COUNTERS};excluded=0;latencies=[];paths={'hit':[],'miss':[],'error':[]};queue=0
            for raw in events:
                if type(raw)is not str or len(raw.encode('utf-8'))>8192:raise ValueError('bounded raw event required')
                event=loads(raw);exact(event,EVENT_FIELDS);request=identifier(event['id'])
                if request in seen:raise ValueError('logical request counted more than once')
                seen.add(request)
                if event['business_id']!=business or event['window_id']!=name:raise ValueError('mixed trace binding')
                if not start<=integer(event['ts_ms'])<end:raise ValueError('event outside closed window')
                if event['scope']not in ('remote','local')or event['outcome']not in ('full','null','partial','miss','error'):raise ValueError('scope or outcome')
                integer(event['lookups'],1,16);integer(event['attempts'],1,8);integer(event['bytes'],0,10**8)
                for key in ('cache_ms','origin_ms','queue_ms'):integer(event[key],0,10**6)
                if type(event['request_error'])is not bool:raise ValueError('request_error boolean')
                hit=event['outcome']in('full','null')
