                path='hit'if hit else 'error'if event['outcome']=='error'else'miss'
                if hit:totals['hit_requests']+=1;totals['hit_bytes']+=event['bytes']
                elif path=='error':totals['cache_errors']+=1
                else:totals['miss_requests']+=1
                elapsed=event['cache_ms']+event['origin_ms']+event['queue_ms'];latencies.append(elapsed);paths[path].append(elapsed);queue+=event['queue_ms']
            if totals!=native:raise ValueError('native counters and logical trace census differ')
            if totals['requests']==0 or totals['bytes']==0:raise ValueError('zero request or byte denominator')
            cost=definition['unit_origin_ms']
            row={**totals,'excluded_local':excluded,'queue_ms':queue,'p95_ms':p95(latencies),'path_p95_ms':{key:p95(values)for key,values in paths.items()},'cost_eligible':totals['requests']*cost,'cost_saved':totals['hit_requests']*cost,'modeled_saved_origin_ms':totals['hit_requests']*definition['unit_origin_ms']}
            row.update(request_hit_rate=totals['hit_requests']/totals['requests'],byte_hit_rate=totals['hit_bytes']/totals['bytes'],value_cost_hit_rate=row['cost_saved']/row['cost_eligible'])
            businesses[business]=row;all_latencies.extend(latencies)
        additive=COUNTERS|{'excluded_local','queue_ms','cost_eligible','cost_saved','modeled_saved_origin_ms'}
        total={key:sum(row[key]for row in businesses.values())for key in additive};total.update(p95_ms=p95(all_latencies),request_hit_rate=total['hit_requests']/total['requests'],byte_hit_rate=total['hit_bytes']/total['bytes'],value_cost_hit_rate=total['cost_saved']/total['cost_eligible'])
        windows[name]={'businesses':businesses,'total':total}
    return windows

def evaluate(snapshot):
    windows=derive(snapshot);spec=snapshot['spec'];before=windows[spec['before']];after=windows[spec['after']];a=after['total'];b=before['total'];minimum=spec['minimum_cost_hit_rate']
    checks={'value_cost_hit_rate_not_regressed':Fraction(a['cost_saved'],a['cost_eligible'])>=Fraction(b['cost_saved'],b['cost_eligible']),'value_cost_hit_rate_minimum':Fraction(a['cost_saved'],a['cost_eligible'])>=Fraction(minimum['num'],minimum['den']),'origin_budget':a['origin_ms']<=spec['max_origin_ms']}
    for business in spec['businesses']:
        name=business['id'];current=after['businesses'][name];previous=before['businesses'][name]
        checks[name+':latency_budget']=current['p95_ms']<=business['max_p95_ms'];checks[name+':latency_no_regression']=current['p95_ms']<=previous['p95_ms'];checks[name+':errors_no_regression']=current['request_errors']<=previous['request_errors']
    metrics={'schema':1,'windows':windows,'coverage':{'scope':'complete finite supplied closed windows','unlinked_requests':0,'production_sampling_error_bound':None,'origin_savings_are_modeled':True}}
    decision={'schema':1,'accepted':all(checks.values()),'checks':checks}
    rows=[]
    for window in (spec['before'],spec['after']):
        for name in sorted(windows[window]['businesses']):
            row=windows[window]['businesses'][name];rows.append([window,name]+[row[key]for key in ('requests','hit_requests','byte_hit_rate','value_cost_hit_rate','p95_ms','origin_ms','queue_ms','request_errors','excluded_local')])
    return metrics,decision,rows

CSV_FIELDS=['window','business','requests','hit_requests','byte_hit_rate','value_cost_hit_rate','p95_ms','origin_ms','queue_ms','request_errors','excluded_local']

