"""Read-only Redis evidence and staged single-writer project products."""
import csv,hashlib,io,json,math,os,pathlib,shutil,tempfile
import model
from decimal import Decimal,InvalidOperation

RATIO_FIELDS={'request_hit_rate','byte_hit_rate','value_cost_hit_rate'}

def encoded(value):return (json.dumps(value,ensure_ascii=False,sort_keys=True,allow_nan=False,indent=2)+'\n').encode('utf-8')
def digest(value):return hashlib.sha256(value).hexdigest()

def _hash(command,key):
    values=command('HGETALL',key)
    if type(values)is not list or len(values)%2:raise ValueError('invalid native hash')
    return dict(zip(values[::2],values[1::2]))

