        key=spec['prefix']+':window:'+window;meta=_hash(command,key);businesses=[]
        for business in spec['businesses']:
            suffix=window+':'+business['id']
            businesses.append({'id':business['id'],'stats':_hash(command,spec['prefix']+':stats:'+suffix),'events':command('LRANGE',spec['prefix']+':events:'+suffix,0,-1)})
        if _hash(command,key)!=meta:raise ValueError('window changed during capture')
