    directory=generation/phase
    if directory.is_symlink()or not directory.is_dir():raise ValueError('missing or linked phase')
    expected=set(names)|{'manifest.json'}
    if {path.name for path in directory.iterdir()}!=expected:raise ValueError('unexpected phase files')
    for name in expected:
        path=directory/name
        if path.is_symlink()or not path.is_file():raise ValueError('invalid phase artifact')
    manifest=model.loads((directory/'manifest.json').read_text(encoding='utf-8'));model.exact(manifest,names)
    result={name:(directory/name).read_bytes()for name in names}
    if manifest!={name:digest(data)for name,data in result.items()}:raise ValueError('artifact digest mismatch')
    return result

