    complete={**artifacts,'manifest.json':encoded({name:digest(data)for name,data in artifacts.items()})}
    if target.exists():
        previous=read_phase(generation,phase,set(artifacts))
        if previous!=artifacts:raise ValueError('immutable phase differs')
